{"id":"78106971-68f9-4d2e-9dbe-9fabf40f33e0","inserted_at":"2026-04-14T11:18:51.323034+00:00","updated_at":"2026-04-14T11:18:51.323034+00:00","type":"sql","name":"Auto-creazione profili utente","description":"","content":{"sql":"-- Funzione per creare un profilo automatico al momento del login/registrazione\r\nCREATE OR REPLACE FUNCTION public.handle_new_user()\r\nRETURNS trigger AS $$\r\nBEGIN\r\n  INSERT INTO public.profiles (id, user_persona, party_size)\r\n  VALUES (new.id, 'Standard', 1);\r\n  RETURN NEW;\r\nEND;\r\n$$ LANGUAGE plpgsql SECURITY DEFINER;\r\n\r\n-- Trigger che attiva la funzione ogni volta che viene creato un utente in auth.users\r\nCREATE OR REPLACE TRIGGER on_auth_user_created\r\n  AFTER INSERT ON auth.users\r\n  FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();\r\n\r\n-- Creiamo i profili per gli utenti già esistenti (se ce ne sono)\r\nINSERT INTO public.profiles (id, user_persona, party_size)\r\nSELECT id, 'Standard', 1\r\nFROM auth.users\r\nON CONFLICT (id) DO NOTHING;\r\n","content_id":"78106971-68f9-4d2e-9dbe-9fabf40f33e0","schema_version":"1.0"},"visibility":"user","favorite":false,"project":{"id":27102476,"ref":"fsuolbwsvpgiglwcaffh","name":"loto.hub","base_project_id":null},"owner":{"id":10709404,"username":"lototaranto-alt"},"updated_by":{"id":10709404,"username":"lototaranto-alt"},"message":""}
